-- P18 authorization hardening: separate daily management, legal consent and AUTOPILOT ownership.
create or replace function private.marketing_manage_access(p_org uuid,p_actor uuid default auth.uid())returns boolean language sql stable security definer set search_path=pg_catalog,private as $$select p_actor is not null and(private.has_org_role(p_org,array['CLIENT_OWNER','CLIENT_ADMIN','PROVIDER_OWNER','PROVIDER_MANAGER','FRANCHISE_OWNER','FRANCHISE_MANAGER'],p_actor)or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN'],p_actor))$$;
create or replace function private.marketing_consent_access(p_org uuid,p_actor uuid default auth.uid())returns boolean language sql stable security definer set search_path=pg_catalog,private as $$select p_actor is not null and private.has_org_role(p_org,array['CLIENT_OWNER','PROVIDER_OWNER','FRANCHISE_OWNER'],p_actor)$$;
create or replace function private.marketing_autopilot_owner_access(p_org uuid,p_actor uuid default auth.uid())returns boolean language sql stable security definer set search_path=pg_catalog,private as $$select p_actor is not null and private.has_org_role(p_org,array['CLIENT_OWNER','PROVIDER_OWNER','FRANCHISE_OWNER'],p_actor)$$;

create or replace function public.record_marketing_consent(p_organization_id uuid,p_purpose text,p_decision text,p_policy_version text,p_evidence_hash text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();h text;cached jsonb;r jsonb;c uuid;begin if a is null or not private.marketing_consent_access(p_organization_id,a)then raise exception'MARKETING_CONSENT_OWNER_REQUIRED'using errcode='42501';end if;if p_purpose not in('SOCIAL_PUBLISHING','MARKETING_ANALYTICS','PERSONAL_DATA_CONTENT')or p_decision not in('GRANTED','WITHDRAWN')or length(btrim(coalesce(p_policy_version,'')))<1 or p_evidence_hash!~'^[0-9a-f]{64}$'then raise exception'INVALID_MARKETING_CONSENT'using errcode='22023';end if;perform pg_advisory_xact_lock(hashtextextended('marketing-consent:'||p_organization_id::text||':'||p_purpose,0));h:=private.canonical_request_hash(jsonb_build_object('org',p_organization_id,'purpose',p_purpose,'decision',p_decision,'policy',p_policy_version,'evidence',p_evidence_hash));cached:=private.begin_contract_command(p_organization_id,'marketing.consent.'||p_purpose,p_idempotency_key,h,a);if cached is not null then return cached;end if;insert into public.marketing_consents(organization_id,purpose,decision,policy_version,evidence_hash,decided_by)values(p_organization_id,p_purpose,p_decision,p_policy_version,p_evidence_hash,a)returning id into c;if p_purpose='SOCIAL_PUBLISHING'and p_decision='WITHDRAWN'then update public.social_publication_jobs set status='SKIPPED'where organization_id=p_organization_id and status='QUEUED';update public.marketing_calendar_items i set status='SKIPPED'from public.marketing_campaigns m where i.campaign_id=m.id and m.organization_id=p_organization_id and i.status='SCHEDULED';end if;r:=jsonb_build_object('outcome','MARKETING_CONSENT_'||p_decision,'consent_id',c,'purpose',p_purpose);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','marketing.consent.'||lower(p_decision),'marketing_consent',c::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'marketing_consent',c::text,'MarketingConsent'||initcap(lower(p_decision))||'V1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_organization_id,'marketing.consent.'||p_purpose,p_idempotency_key,r);return r;end$$;

create or replace function public.create_marketing_campaign(p_organization_id uuid,p_brand_kit_version_id uuid,p_mode text,p_title_fr text,p_title_ar text,p_frequency_max_weekly integer,p_risk_threshold integer,p_audience_snapshot jsonb,p_source_snapshot jsonb,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();b public.brand_kits%rowtype;h text;cached jsonb;r jsonb;c uuid;begin select k.*into b from public.brand_kits k join public.brand_kit_versions v on v.brand_kit_id=k.id where v.id=p_brand_kit_version_id;if a is null or not found or b.organization_id<>p_organization_id or not private.marketing_manage_access(p_organization_id,a)then raise exception'MARKETING_CAMPAIGN_DENIED'using errcode='42501';end if;if b.status<>'READY'or p_mode not in('MANUAL','ASSISTED','AUTOPILOT')or(p_mode='AUTOPILOT'and(not private.marketing_autopilot_owner_access(p_organization_id,a)or not private.marketing_consent_active(p_organization_id,'SOCIAL_PUBLISHING')or not exists(select 1 from public.social_connections where organization_id=p_organization_id and status='ACTIVE')))or length(btrim(p_title_fr))<3 or length(btrim(p_title_ar))<2 or p_frequency_max_weekly not between 1 and 50 or p_risk_threshold not between 0 and 100 or jsonb_typeof(p_audience_snapshot)<>'object'or jsonb_typeof(p_source_snapshot)<>'object'then raise exception'INVALID_MARKETING_CAMPAIGN'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('org',p_organization_id,'brand',p_brand_kit_version_id,'mode',p_mode,'fr',p_title_fr,'ar',p_title_ar,'frequency',p_frequency_max_weekly,'risk',p_risk_threshold,'audience',p_audience_snapshot,'source',p_source_snapshot));cached:=private.begin_contract_command(p_organization_id,'marketing.campaign.create',p_idempotency_key,h,a);if cached is not null then return cached;end if;insert into public.marketing_campaigns(organization_id,brand_kit_version_id,mode,title_fr,title_ar,frequency_max_weekly,risk_threshold,audience_snapshot,source_snapshot,created_by)values(p_organization_id,p_brand_kit_version_id,p_mode,p_title_fr,p_title_ar,p_frequency_max_weekly,p_risk_threshold,p_audience_snapshot,p_source_snapshot,a)returning id into c;r:=jsonb_build_object('outcome','MARKETING_CAMPAIGN_CREATED','campaign_id',c,'mode',p_mode);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','marketing.campaign.created','marketing_campaign',c::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'marketing_campaign',c::text,'MarketingCampaignCreatedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_organization_id,'marketing.campaign.create',p_idempotency_key,r);return r;end$$;

revoke all on function private.marketing_consent_access(uuid,uuid),private.marketing_autopilot_owner_access(uuid,uuid)from public,anon,authenticated,service_role;
notify pgrst,'reload schema';
